mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("weights=[1,3,4,5] values=[1,4,5,7]","9"),
        ("weights=[7] values=[10]","10"),
        ("weights=[2,2,3] values=[3,4,5]","12"),
        ("weights=[8] values=[99]","0"),
        ("weights=[1,6] values=[2,8]","10"),
        ("  \nweights=[1,3,4,5] values=[1,4,5,7]\n  ","9"),
        ("\nweights=[1,6] values=[2,8]\n","10")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS zero-one-knapsack");
}
